challenge.solution:
const signals = ["bip", "vuu", "bip", "tık", "bip", "vuu"];

function countWords(list) {
  const counts = new Map();
  // her kelimeyi say
  for (const word of list) {
    counts.set(word, (counts.get(word) || 0) + 1);
  }
  return counts;
}

function mostCommon(list) {
  // en çok geçen kelime
  let best = null;
  let bestCount = 0;
  for (const [word, count] of countWords(list)) {
    if (count > bestCount) {
      best = word;
      bestCount = count;
    }
  }
  return best;
}

console.log(countWords(signals));
console.log("En sık:", mostCommon(signals));

check.js:
const m = countWords(signals);
assert(m instanceof Map, "countWords bir Map döndürmeli.");
assert(m.get("bip") === 3 && m.get("vuu") === 2 && m.get("tık") === 1 && m.size === 3, "bip 3, vuu 2, tık 1 olmalı.");
const m2 = countWords(["a", "a"]);
assert(m2.get("a") === 2 && m2.size === 1, "countWords başka listelerle de çalışmalı.");
assert(mostCommon(signals) === "bip", "mostCommon(signals) 'bip' olmalı.");
assert(mostCommon(["x", "y", "y", "z"]) === "y", "mostCommon başka listelerde de en sık kelimeyi bulmalı.");

