const defaults = { theme: "light", fontSize: 16, lang: "tr" };
const savedText = '{"theme":"dark","fontSize":18}';

function loadSettings(text) {
  // JSON'u çöz, varsayılanlarla birleştir
  return { ...defaults, ...JSON.parse(text) };
}

function saveSettings(settings) {
  // JSON metnine çevir
  return JSON.stringify(settings);
}

const settings = loadSettings(savedText);
console.log(settings);
console.log(saveSettings(settings));

check.js:
const s = loadSettings(savedText);
assert(s && s.theme === "dark" && s.fontSize === 18 && s.lang === "tr", "loadSettings(savedText) { theme: 'dark', fontSize: 18, lang: 'tr' } olmalı.");
const s2 = loadSettings('{"lang":"en"}');
assert(s2.theme === "light" && s2.fontSize === 16 && s2.lang === "en", "Kayıtta olmayan ayarlar defaults'tan gelmeli.");
assert(defaults.theme === "light" && defaults.lang === "tr", "defaults nesnesi değişmemeli; spread ile yeni nesne oluştur.");
const text = saveSettings(s);
assert(typeof text === "string" && same(JSON.parse(text), s), "saveSettings ayarları JSON metnine çevirmeli.");

