const tasks = [
  { title: "Matematik ödevi", done: true },
  { title: "Fizik tekrarı", done: false },
];

function saveTasks(list) {
  // JSON metnine çevir
  return JSON.stringify(list);
}

function loadTasks(text) {
  // boşsa [], değilse JSON.parse
  if (!text) return [];
  return JSON.parse(text);
}

const saved = saveTasks(tasks);
console.log(saved);
console.log(loadTasks(saved));
console.log(loadTasks(""));

check.js:
const saved = saveTasks(tasks);
assert(typeof saved === "string", "saveTasks bir metin döndürmeli.");
const back = loadTasks(saved);
assert(Array.isArray(back) && back !== tasks && same(back, tasks), "loadTasks(saveTasks(tasks)) aynı görevleri (yeni bir dizi olarak) vermeli.");
assert(Array.isArray(loadTasks("")) && loadTasks("").length === 0, "loadTasks(\"\") boş dizi döndürmeli.");
assert(Array.isArray(loadTasks(null)) && loadTasks(null).length === 0, "loadTasks(null) boş dizi döndürmeli.");
assert(same(loadTasks('[{"title":"X","done":false}]'), [{ title: "X", done: false }]), "loadTasks verilen JSON metnini çözmeli.");

