project_task.solution:
const packText = '{"name":"Gezegenler","questions":[' +
  '{"text":"Kızıl gezegen hangisi?","options":["Mars","Venüs","Merkür"],"answer":0},' +
  '{"text":"En büyük gezegen hangisi?","options":["Satürn","Jüpiter","Neptün"],"answer":1},' +
  '{"text":"Halkalı gezegen hangisi?","options":["Uranüs","Mars","Satürn"],"answer":2}]}';

function describePack(text) {
  // JSON.parse ile paketi aç
  const pack = JSON.parse(text);
  return `${pack.name}: ${pack.questions.length} soru`;
}

function correctAnswers(text) {
  // her sorunun doğru seçeneği
  const pack = JSON.parse(text);
  return pack.questions.map((q) => q.options[q.answer]);
}

console.log(describePack(packText));
console.log(correctAnswers(packText));

check.js:
assert(describePack(packText) === "Gezegenler: 3 soru", "describePack(packText) 'Gezegenler: 3 soru' döndürmeli.");
assert(same(correctAnswers(packText), ["Mars", "Jüpiter", "Satürn"]), "correctAnswers(packText) ['Mars', 'Jüpiter', 'Satürn'] döndürmeli.");
const other = JSON.stringify({ name: "Hayvanlar", questions: [{ text: "En büyük hayvan?", options: ["Fil", "Mavi balina"], answer: 1 }] });
assert(describePack(other) === "Hayvanlar: 1 soru", "describePack başka paketlerle de çalışmalı.");
assert(same(correctAnswers(other), ["Mavi balina"]), "correctAnswers başka paketlerle de çalışmalı.");
